'use strict';
// All products, prices, sizes and cart contents are presentation-only sample data.
const products = [
  {id:'city-white',name:'Кроссовки City White',category:'sneakers',type:'Лайфстайл-кроссовки',gender:'unisex',price:32900,image:6705219,color:'Белый',swatch:'#efeee8',sizes:[36,37,38,39,40,41,42,43],badge:'НОВИНКА',desc:'Чистый силуэт и белый цвет, который легко вписать в повседневный гардероб. Пара для прогулок без определённого маршрута.',material:'Гладкий верх · текстильная подкладка',bg:'#1c211e'},
  {id:'daily-grey',name:'Кроссовки Daily Grey',category:'sneakers',type:'Кроссовки для города',gender:'unisex',price:38900,image:26852035,color:'Светло-серый',swatch:'#bcc4d4',sizes:[37,38,39,40,41,42,43,44],badge:'ВЫБОР INSTOCK',desc:'Лёгкая фактура, спокойная палитра и спортивный характер. Для дней, в которых много движения.',material:'Текстильный верх · рельефная подошва',bg:'#b2bbc9'},
  {id:'chelsea-black',name:'Челси Black Line',category:'boots',type:'Ботинки челси',gender:'unisex',price:54900,image:35654955,color:'Чёрный',swatch:'#242424',sizes:[37,38,39,40,41,42,43,44],badge:'СЕЗОННЫЙ ВЫБОР',desc:'Лаконичные челси с эластичными вставками и выразительной подошвой. Городская классика для прохладных дней.',material:'Гладкий верх · эластичные вставки',bg:'#d5c9b9'},
  {id:'classic-loafer',name:'Лоферы Classic Noir',category:'loafers',type:'Классические лоферы',gender:'men',price:45900,image:10259873,color:'Чёрный',swatch:'#222',sizes:[40,41,42,43,44,45],badge:'КЛАССИКА',desc:'Сдержанная форма и мягкий блеск. Лоферы для тех случаев, когда образу нужна собранность без лишней строгости.',material:'Гладкий фактурный верх · низкий каблук',bg:'#101010'},
  {id:'run-light',name:'Кроссовки Run Light',category:'sneakers',type:'Беговой силуэт',gender:'unisex',price:29900,image:23491456,color:'Молочный',swatch:'#e2e1d9',sizes:[36,37,38,39,40,41,42,43],badge:'ЛЁГКИЙ ШАГ',desc:'Сетчатая фактура и светлая палитра. Спортивный акцент в привычном повседневном образе.',material:'Сетчатый верх · гибкий силуэт',bg:'#030303'},
  {id:'canvas-high',name:'Кеды Canvas High',category:'canvas',type:'Высокие кеды',gender:'unisex',price:27900,image:13924826,color:'Кремовый',swatch:'#d6c4a7',sizes:[36,37,38,39,40,41,42,43,44],badge:'TIMELESS',desc:'Высокий силуэт, тканевая фактура и знакомый характер кед. С джинсами, широкими брюками или любимым платьем.',material:'Текстильный верх · резиновая подошва',bg:'#b5aa90'},
  {id:'ballet-rose',name:'Балетки Rose Detail',category:'women',type:'Балетки с декором',gender:'women',price:24900,image:6387628,color:'Персиковый',swatch:'#df9c7e',sizes:[35,36,37,38,39,40],badge:'ДЕТАЛИ РЕШАЮТ',desc:'Тёплый оттенок и декоративная отделка для образов с настроением. Выразительная пара на особенный день.',material:'Декоративная отделка · плоская подошва',bg:'#526d6e'},
  {id:'sandals-sand',name:'Слайды Sand',category:'sandals',type:'Слайды с пряжками',gender:'unisex',price:18900,image:37305536,color:'Песочный',swatch:'#dac8a9',sizes:[36,37,38,39,40,41,42,43],badge:'SLOW DAYS',desc:'Открытый силуэт и три пряжки. Для тёплых дней и моментов, когда никуда не нужно спешить.',material:'Фактурная подошва · три пряжки',bg:'#e6c9a5'},
];
const categories=[['all','Все пары'],['sneakers','Кроссовки'],['canvas','Кеды'],['boots','Ботинки'],['loafers','Лоферы'],['women','Женская классика'],['sandals','Сандалии и слайды']];
const genderNames={all:'Все',unisex:'Унисекс',women:'Женщинам',men:'Мужчинам'};
const main=document.querySelector('#main'),homeMarkup=main.innerHTML,panel=document.querySelector('#panel'),sizeDialog=document.querySelector('#size-dialog'),cart=[];
let selectedSize=null,currentProduct=null,toastTimer,routeInitialized=false;
const money=value=>new Intl.NumberFormat('ru-KZ').format(value)+' ₸';
const escapeHtml=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const imageUrl=product=>'assets/shoe-'+product.image+'.jpg';
function productCard(p){return `<article class="product-card"><a class="product-image" href="#/product/${p.id}" aria-label="${p.name}" style="background:${p.bg}"><img src="${imageUrl(p)}" alt="${p.type}, ${p.color.toLowerCase()}" loading="lazy" width="500" height="575"><span class="product-badge ${p.id==='city-white'?'orange':''}">${p.badge}</span><span class="card-arrow" aria-hidden="true">↗</span></a><div class="product-info"><p class="product-meta">${genderNames[p.gender].toUpperCase()} / ${p.type.toUpperCase()}</p><div class="product-name-row"><h3><a href="#/product/${p.id}">${p.name}</a></h3><span class="price">${money(p.price)}</span></div><p class="product-colors"><span class="mini-swatch" style="background:${p.swatch}"></span>${p.color}</p></div></article>`;}
function breadcrumbs(label){return `<nav class="breadcrumbs" aria-label="Хлебные крошки"><a href="#/">Главная</a><span>/</span>${label}</nav>`;}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3200);}
function routeParts(){const hash=location.hash.slice(1)||'/',split=hash.indexOf('?');return{path:split<0?hash:hash.slice(0,split),params:new URLSearchParams(split<0?'':hash.slice(split+1))};}
function catalogHref(updates={}){const{params}=routeParts();for(const[key,value]of Object.entries(updates)){if(value&&value!=='all')params.set(key,value);else params.delete(key);}return '#/catalog'+(params.size?'?'+params.toString():'');}
function renderHome(){main.innerHTML=homeMarkup;document.querySelector('#home-products').innerHTML=products.slice(0,4).map(productCard).join('');main.insertAdjacentHTML('beforeend',`<section class="brand-strip"><div><span class="eyebrow">НЕ ПОДСТРАИВАЙСЯ. ВЫБИРАЙ СВОЁ.</span><h2>Один город.<br>Тысячи маршрутов.</h2><a href="#/about" class="text-link">Это InStock Astana <span>↗</span></a></div><p>Лайфстайл или классика, знакомый силуэт или что-то новое. Мы собираем обувь, которая оставляет место для твоего характера.</p><span class="brand-strip-mark" aria-hidden="true">is.</span></section>`);document.title='InStock Astana — В твоём ритме';}
function filteredProducts(params){const gender=params.get('gender')||'all',category=params.get('category')||'all',q=(params.get('q')||'').trim().toLowerCase(),size=Number(params.get('size'))||0;let list=products.filter(p=>(gender==='all'||p.gender===gender||(gender!=='unisex'&&p.gender==='unisex'))&&(category==='all'||p.category===category)&&(!size||p.sizes.includes(size))&&(!q||`${p.name} ${p.type} ${p.color}`.toLowerCase().includes(q)));if(params.get('sort')==='price-asc')list.sort((a,b)=>a.price-b.price);if(params.get('sort')==='price-desc')list.sort((a,b)=>b.price-a.price);return list;}
function renderCatalog(params){const list=filteredProducts(params),gender=params.get('gender')||'all',category=params.get('category')||'all',q=params.get('q')||'',title=q?'Результаты поиска':gender==='all'?'Найди свою пару.':genderNames[gender]||'Каталог';document.title=title+' — InStock Astana';main.innerHTML=`<div class="catalog-page section-wrap">${breadcrumbs('Каталог')}<div class="catalog-heading"><div><p class="eyebrow">THE INSTOCK SELECTION / 2026</p><h1>${escapeHtml(title)}</h1><p>${q?'По запросу «'+escapeHtml(q)+'»':'Для любого дня. В твоём стиле.'}</p></div><span class="catalog-index">[ ${String(list.length).padStart(2,'0')} ПАР ]</span></div><div class="gender-tabs" aria-label="Коллекции">${Object.entries(genderNames).map(([key,label])=>`<a href="${catalogHref({gender:key})}" class="${gender===key?'active':''}" ${gender===key?'aria-current="page"':''}>${label}</a>`).join('')}</div><div class="category-tabs" aria-label="Категории">${categories.map(([key,label])=>`<a href="${catalogHref({category:key})}" class="${category===key?'active':''}">${label}</a>`).join('')}</div><div class="catalog-toolbar"><label class="catalog-search"><svg viewBox="0 0 24 24"><circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/></svg><input id="catalog-search" type="search" placeholder="Название или цвет" aria-label="Поиск в каталоге" value="${escapeHtml(q)}"><button type="button" data-action="catalog-search" aria-label="Найти в каталоге">↗</button></label><div class="catalog-selects"><label>Размер <select id="size-filter" aria-label="Фильтр по размеру"><option value="all">Все</option>${Array.from({length:11},(_,i)=>i+35).map(s=>`<option ${params.get('size')===String(s)?'selected':''}>${s}</option>`).join('')}</select></label><label class="sort-label"><span>Сортировка</span><select id="sort-filter" aria-label="Сортировка"><option value="featured">Рекомендуем</option><option value="price-asc" ${params.get('sort')==='price-asc'?'selected':''}>Сначала дешевле</option><option value="price-desc" ${params.get('sort')==='price-desc'?'selected':''}>Сначала дороже</option></select></label></div></div><p class="results-count" role="status">Найдено: ${list.length}${params.size?' <a href="#/catalog">Сбросить фильтры ×</a>':''}</p>${list.length?`<div class="product-grid">${list.map(productCard).join('')}</div>`:`<div class="empty-state"><span class="empty-symbol">↗</span><h2>Этой пары пока нет.</h2><p>Попробуй другой запрос, размер или категорию.</p><a class="button button-dark" href="#/catalog">Посмотреть все пары <span>↗</span></a></div>`}<div class="catalog-note"><span>ПАРА ДЛЯ КАЖДОГО МАРШРУТА</span><p>В прототипе показана часть коллекции. Фотографии, описания, размеры и цены используются для демонстрации.</p></div></div>`;}
function renderProduct(id){const p=products.find(item=>item.id===id);if(!p){renderNotFound();return;}currentProduct=p;selectedSize=null;document.title=p.name+' — InStock Astana';main.innerHTML=`<div class="product-page section-wrap">${breadcrumbs(`<a href="#/catalog">Каталог</a><span>/</span><span>${p.name}</span>`)}<div class="product-detail"><div class="detail-image" style="background:${p.bg}"><img src="${imageUrl(p)}" alt="${p.name} — ${p.color}" width="800" height="920"><span class="product-badge">${p.badge}</span><span class="image-count">01 / 01</span></div><div class="detail-copy"><p class="eyebrow">${genderNames[p.gender].toUpperCase()} / INSTOCK SELECTION</p><h1>${p.name}</h1><p class="detail-type">${p.type}</p><p class="detail-price">${money(p.price)}</p><div class="detail-color"><span class="swatch" style="background:${p.swatch}"></span>Цвет: ${p.color}</div><div class="size-heading"><label id="size-label">Размер EU <span id="selected-size"></span></label><button data-action="size-guide">Как выбрать размер ↗</button></div><div class="size-grid" role="group" aria-labelledby="size-label">${Array.from({length:11},(_,i)=>i+35).map(s=>`<button data-action="size" data-size="${s}" aria-pressed="false" ${p.sizes.includes(s)?'':'disabled'}>${s}</button>`).join('')}</div><button id="add-to-cart" class="button button-dark full-width" data-action="add" disabled>Выбери размер <span>↗</span></button><p class="demo-note">Демонстрационная карточка. Заказы и платежи не принимаются.</p><div class="product-description"><h3>О паре</h3><p>${p.desc}</p></div><details class="detail-accordion"><summary>Детали и уход <span>+</span></summary><p>${p.material}. Для ухода используй мягкую щётку и средства, подходящие материалу. Характеристики в прототипе условные.</p></details><details class="detail-accordion"><summary>Доставка и возврат <span>+</span></summary><p>Условия доставки, примерки и возврата появятся после запуска магазина. В этом прототипе можно посмотреть подборку и собрать демонстрационную корзину.</p></details></div></div><section class="related"><div class="section-heading"><div><p class="eyebrow">ЕЩЁ В ТВОЁМ РИТМЕ</p><h2>Продолжим выбирать?</h2></div><a href="#/catalog" class="text-link">Весь каталог ↗</a></div><div class="product-grid">${products.filter(item=>item.id!==id).slice(0,4).map(productCard).join('')}</div></section></div>`;}
function renderAbout(){document.title='О бренде — InStock Astana';main.innerHTML=`<div class="about-page section-wrap">${breadcrumbs('О бренде')}<p class="eyebrow">ASTANA, KAZAKHSTAN / 2026</p><h1>Твой город.<br>Твой характер.<br><em>Твоя пара.</em></h1><div class="about-content"><div class="about-photo" role="img" aria-label="Кроссовки на залитых солнцем городских ступенях"></div><div><p class="eyebrow">ЭТО INSTOCK</p><h2>Обувь как часть<br>твоей истории.</h2><p>InStock Astana — пространство для разных стилей и одного простого чувства: быть собой.</p><p>Мы смотрим на город как на место встреч, движения и маленьких открытий. Поэтому в нашей подборке есть и повседневные кроссовки, и выразительные ботинки, и спокойная классика.</p><p>Не обязательно выбирать один стиль. Достаточно найти пару под своё настроение.</p><a class="button button-dark" href="#/catalog">Исследовать коллекцию <span>↗</span></a></div></div><div class="about-values"><div><span>01 / ХАРАКТЕР</span><h3>Место для твоего стиля.</h3><p>От лаконичных силуэтов до заметных деталей.</p></div><div><span>02 / ДВИЖЕНИЕ</span><h3>В ритме твоего дня.</h3><p>Пары для привычных и совершенно новых маршрутов.</p></div><div><span>03 / ГОРОД</span><h3>С чувством Астаны.</h3><p>Современный взгляд, открытый разным историям.</p></div></div></div>`;}
function renderNotFound(){document.title='Страница не найдена — InStock Astana';main.innerHTML='<div class="empty-state section-wrap"><p class="eyebrow">404 / ДРУГОЙ МАРШРУТ</p><h1>Здесь пока пусто.</h1><p>Но твоя следующая пара может быть в каталоге.</p><a class="button button-dark" href="#/catalog">В каталог ↗</a></div>';}
function renderRoute(){const{path,params}=routeParts();panel.close();currentProduct=null;selectedSize=null;if(path==='/'||path==='main')renderHome();else if(path==='/catalog')renderCatalog(params);else if(path.startsWith('/product/'))renderProduct(path.slice(9));else if(path==='/about')renderAbout();else renderNotFound();document.querySelectorAll('[data-nav]').forEach(link=>link.classList.toggle('current',path.includes(link.dataset.nav)));if(routeInitialized){window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});}routeInitialized=true;}
function openPanel(title,content){panel.innerHTML=`<div class="panel-top"><h2>${title}</h2><button data-action="close" class="close-button" aria-label="Закрыть панель">×</button></div>${content}`;if(!panel.open)panel.showModal();}
function openSearch(){openPanel('Найдём твою пару.',`<form id="search-form"><label for="site-search" class="search-label">Название, категория или цвет</label><div class="search-input-row"><input type="search" id="site-search" name="q" placeholder="Например, кроссовки" autocomplete="off"><button class="button button-dark" type="submit" aria-label="Искать">↗</button></div></form><p class="search-hint">Или начни с категории</p><nav class="search-categories">${categories.slice(1).map(([id,label])=>`<a href="#/catalog?category=${id}">${label}<span>↗</span></a>`).join('')}</nav>`);document.querySelector('#site-search').focus();}
function openMenu(){document.querySelector('[data-action="menu"]').setAttribute('aria-expanded','true');openPanel('Выбирай своё.',`<nav class="menu-links"><a href="#/catalog">Все пары <span>↗</span></a><a href="#/catalog?gender=women">Женщинам <span>↗</span></a><a href="#/catalog?gender=men">Мужчинам <span>↗</span></a><a href="#/catalog?gender=unisex">Унисекс <span>↗</span></a><a href="#/about">О бренде <span>↗</span></a></nav><p class="menu-footnote">ASTANA, KAZAKHSTAN<br>В твоём ритме.</p>`);}
function openSizeGuide(){sizeDialog.innerHTML=`<div class="panel-top"><h2 id="size-title">Найди свой размер.</h2><button class="close-button" data-action="close-size" aria-label="Закрыть размерную сетку">×</button></div><p>Измерь длину стопы от пятки до самого длинного пальца. Сравни обе стопы и ориентируйся на большее значение.</p><table><thead><tr><th scope="col">Размер EU</th><th scope="col">Длина стопы, см</th></tr></thead><tbody>${[[35,'22,5'],[36,'23'],[37,'23,5'],[38,'24'],[39,'24,5'],[40,'25,5'],[41,'26'],[42,'26,5'],[43,'27,5'],[44,'28'],[45,'28,5']].map(([s,length])=>`<tr><td>${s}</td><td>${length}</td></tr>`).join('')}</tbody></table><p>Примерная сетка для прототипа. Посадка и размеры зависят от модели и производителя.</p>`;sizeDialog.showModal();}
function selectSize(size){if(!currentProduct?.sizes.includes(size))throw new Error('Этот размер недоступен');selectedSize=size;document.querySelectorAll('[data-action="size"]').forEach(button=>{const active=Number(button.dataset.size)===size;button.setAttribute('aria-pressed',String(active));button.classList.toggle('selected',active);});document.querySelector('#selected-size').textContent=' / '+size;const addButton=document.querySelector('#add-to-cart');addButton.disabled=false;addButton.innerHTML='Добавить в корзину <span>↗</span>';}
function addToCart(product,size){if(!product||!product.sizes.includes(size))throw new Error('Выбери доступный размер');const existing=cart.find(item=>item.id===product.id&&item.size===size);if(existing){if(existing.qty>=9){toast('Максимум 9 одинаковых пар в демо-корзине');return;}existing.qty++;}else cart.push({id:product.id,size,qty:1});updateCount();toast('Пара добавлена в корзину');}
function updateCount(){document.querySelector('#cart-count').textContent=cart.reduce((sum,item)=>sum+item.qty,0);}
function openCart(){if(!cart.length){openPanel('Твоя корзина',`<div class="empty-state cart-empty"><span class="empty-symbol">↗</span><h2>Хорошая пара<br>ещё впереди.</h2><p>Здесь появится обувь, которую ты выберешь.</p><a class="button button-dark" href="#/catalog" data-action="close">Начать выбирать <span>↗</span></a></div>`);return;}const total=cart.reduce((sum,item)=>sum+products.find(p=>p.id===item.id).price*item.qty,0);openPanel(`Твоя корзина <small>(${cart.reduce((n,i)=>n+i.qty,0)})</small>`,`<div class="cart-items">${cart.map((item,index)=>{const p=products.find(p=>p.id===item.id);return `<article class="cart-item"><a href="#/product/${p.id}"><img src="${imageUrl(p)}" alt="${p.name}"></a><div><a class="cart-item-title" href="#/product/${p.id}">${p.name}</a><p>${p.color} / EU ${item.size}</p><span class="price">${money(p.price)}</span><div class="cart-item-actions"><div class="quantity"><button data-action="quantity" data-index="${index}" data-delta="-1" aria-label="Уменьшить количество ${p.name}" ${item.qty===1?'disabled':''}>−</button><span>${item.qty}</span><button data-action="quantity" data-index="${index}" data-delta="1" aria-label="Увеличить количество ${p.name}" ${item.qty===9?'disabled':''}>+</button></div><button class="remove-item" data-action="remove" data-index="${index}">Удалить</button></div></div></article>`;}).join('')}</div><div class="cart-total"><span>Итого</span><strong>${money(total)}</strong></div><p class="cart-disclaimer">Демонстрационная корзина. Наличие и стоимость условные. Данные не сохраняются после перезагрузки.</p><button class="button button-dark full-width" data-action="checkout">Посмотреть заказ <span>↗</span></button><button class="continue-button" data-action="close">Продолжить выбирать</button>`);}
function openOrderPreview(){const total=cart.reduce((sum,item)=>sum+products.find(p=>p.id===item.id).price*item.qty,0);openPanel('Предпросмотр заказа',`<div class="order-preview"><p class="eyebrow">ТВОЙ ВЫБОР</p><h3>Пары, которые<br>ты выбрал<span class="orange">.</span></h3><div class="order-lines">${cart.map(item=>`<p><span>${products.find(p=>p.id===item.id).name}<small>EU ${item.size} · ${item.qty} шт.</small></span><strong>${money(products.find(p=>p.id===item.id).price*item.qty)}</strong></p>`).join('')}</div><div class="cart-total"><span>Итого</span><strong>${money(total)}</strong></div><div class="demo-callout"><strong>Это визуальный прототип</strong><p>Заказ не оформлен. Оплата, доставка и ввод личных данных здесь не предусмотрены.</p></div><button class="button button-dark full-width" data-action="cart">Вернуться в корзину <span>↗</span></button></div>`);}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el){if(event.target.closest('#panel a'))panel.close();return;}const action=el.dataset.action;if(action==='search')openSearch();if(action==='menu')openMenu();if(action==='cart')openCart();if(action==='close')panel.close();if(action==='size-guide')openSizeGuide();if(action==='close-size')sizeDialog.close();if(action==='size')selectSize(Number(el.dataset.size));if(action==='add')addToCart(currentProduct,selectedSize);if(action==='quantity'){const item=cart[Number(el.dataset.index)];if(item)item.qty=Math.max(1,Math.min(9,item.qty+Number(el.dataset.delta)));updateCount();openCart();}if(action==='remove'){cart.splice(Number(el.dataset.index),1);updateCount();openCart();toast('Пара удалена из корзины');}if(action==='checkout')openOrderPreview();if(action==='catalog-search')location.hash=catalogHref({q:document.querySelector('#catalog-search').value.trim()});});
document.addEventListener('submit',event=>{if(event.target.id==='search-form'){event.preventDefault();const q=document.querySelector('#site-search').value.trim();panel.close();location.hash='#/catalog'+(q?'?q='+encodeURIComponent(q):'');}});
document.addEventListener('change',event=>{if(event.target.id==='size-filter')location.hash=catalogHref({size:event.target.value});if(event.target.id==='sort-filter')location.hash=catalogHref({sort:event.target.value==='featured'?'':event.target.value});});
document.addEventListener('keydown',event=>{if(event.target.id==='catalog-search'&&event.key==='Enter'){event.preventDefault();location.hash=catalogHref({q:event.target.value.trim()});}});
panel.addEventListener('close',()=>document.querySelector('[data-action="menu"]').setAttribute('aria-expanded','false'));
for(const dialog of [panel,sizeDialog])dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close();}});
window.addEventListener('hashchange',renderRoute);renderRoute();
document.querySelector('.skip-link').addEventListener('click',event=>{event.preventDefault();main.focus();main.scrollIntoView({block:'start'});});
// Optional browser-agent tools share the same visible demo actions.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const definitions=[{name:'read_demo_catalog',title:'Просмотреть демонстрационный каталог',description:'Read sample shoes, demonstration prices and sizes. No live stock data.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>products.map(({id,name,price,sizes})=>({id,name,price,currency:'KZT',sizes}))},{name:'add_to_demo_cart',title:'Добавить пару в демо-корзину',description:'Stage one sample shoe and size in the visible in-memory cart. Does not order, pay or persist anything.',inputSchema:{type:'object',properties:{productId:{type:'string'},size:{type:'integer'}},required:['productId','size'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||typeof input.productId!=='string'||!Number.isInteger(input.size))throw new Error('Нужны productId и целый размер');const p=products.find(item=>item.id===input.productId);if(!p||!p.sizes.includes(input.size))throw new Error('Товар или размер недоступен');addToCart(p,input.size);openCart();return{demo:true,cart:cart.map(item=>({...item}))};}}];for(const definition of definitions){try{Promise.resolve(document.modelContext.registerTool(definition,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
